UPDATE "products" SET "name" = 'S14JW', "summary" = '1.4 t walk-behind electric stacker for occasional lifting in compact stores.', "highlights" = '["1,400 kg capacity", "24 V 210 Ah LFP battery", "1,456 mm turning radius"]'::jsonb, "specs" = '{"ratedCapacity": 1400, "operatorPosition": "Pedestrian (walkie)", "voltage": 24, "batteryCapacity": 210, "turningRadius": 1456, "serviceWeight": 1200}'::jsonb, "specs_verified" = true, "order" = 2 WHERE "slug" = 'byd-s14jw';
--> statement-breakpoint
UPDATE "families" SET "name" = 'Pallet Trucks', "summary" = 'Powered 2 t pallet trucks, walk-behind or stand-on, for moving pallets quickly across warehouse floors and loading docks.', "how_it_works" = 'An **electric pallet truck** (powered pallet jack) moves pallets across the floor. It lifts a pallet only a short way, just enough to clear the ground, and is not built for stacking. The operator walks behind it or stands on a platform and steers with a **tiller arm** that holds all the controls: travel direction and speed, lift and lower, horn, and a belly-button reversing switch for safety.

**Drive.** A single drive wheel under the power unit is driven by an AC traction motor and steered by the tiller. Two load wheels under the fork tips carry the pallet. Releasing the tiller or pushing it to the upper or lower position applies an electromagnetic brake. Lifting off the throttle gives regenerative slowing.

**Lift.** A small electric hydraulic power pack pushes a cylinder that raises the fork frame. Linkage rods running along each fork push the load wheels down at the same time, so the whole pallet lifts evenly.

**Battery.** BYD pallet trucks run on 24 V lithium iron phosphate (LFP) batteries. Many have an on-board charger that plugs into a normal socket, so the truck can be charged anywhere during a break. The battery management system (BMS) protects the cells from over-charge, over-discharge and overheating.

**Variants.** Walkie (pedestrian) trucks suit short runs and tight spaces. Stand-on platform trucks are faster and suit longer distances, such as dock-to-store runs in large distribution centres. BYD also offers pallet trucks with higher lift for working at waist height in retail stores.', "order" = 5 WHERE "slug" = 'pallet-trucks';
--> statement-breakpoint
UPDATE "products" SET "name" = 'P20JW', "summary" = '2.0 t walk-behind electric pallet truck on a 24 V LFP battery.', "highlights" = '["2,000 kg capacity", "24 V 210 Ah LFP battery", "1,515 mm turning radius", "Light 490 kg truck"]'::jsonb, "specs" = '{"ratedCapacity": 2000, "operatorPosition": "Pedestrian (walkie)", "voltage": 24, "batteryCapacity": 210, "turningRadius": 1515, "serviceWeight": 490}'::jsonb, "specs_verified" = true, "order" = 0 WHERE "slug" = 'byd-p20jw';
